// KeyGeneratorStubOption configures a [KeyGeneratorStub] at its
// construction.
type KeyGeneratorStubOption func(*KeyGeneratorStub)

// KeyGeneratorStubStrict returns the option that makes an unconfigured
// method fail the test instead of returning its zero value.
func KeyGeneratorStubStrict() KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) { s.strict = true }
}

// KeyGeneratorStubDelegateTo returns the option that passes each call to
// impl. The double still records the call.
func KeyGeneratorStubDelegateTo(impl crypto.KeyGenerator) KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) {
		s.OnGenerateKey.Func(impl.GenerateKey)
		s.OnKeyID.Func(impl.KeyID)
		s.OnWrap.Func(impl.Wrap)
		s.OnUnwrap.Func(impl.Unwrap)
	}
}

// KeyGeneratorStubWithClock returns the option that sets the clock of the
// double to clk. The double takes the latency, the windows of the faults
// and the instants of the calls from clk. A latency on a controlled clock
// costs no real time.
func KeyGeneratorStubWithClock(clk assert.Clock) KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) { s.group.SetClock(clk) }
}

// KeyGeneratorStubWithRandSource returns the option that sets the random
// source of the probabilistic faults to src. A seeded source repeats the
// faults of a run.
func KeyGeneratorStubWithRandSource(src rand.Source) KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) { s.group.SetRandSource(src) }
}

// KeyGeneratorStubBenchMode returns the option that turns the recording of
// calls off. The methods still return their results.
func KeyGeneratorStubBenchMode() KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) { s.group.BenchMode() }
}

// KeyGeneratorStubWithLatency returns the option that makes every method
// sleep d before it returns. Without KeyGeneratorStubWithClock, d passes
// in real time.
func KeyGeneratorStubWithLatency(d time.Duration) KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) { s.group.SetLatency(d) }
}

// KeyGeneratorStubFailing returns the option that arms err on each method
// that can fail. Each call of such a method then fails with err.
func KeyGeneratorStubFailing(err error) KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) {
		s.OnGenerateKey.Faults(err, 1)
		s.OnWrap.Faults(err, 1)
		s.OnUnwrap.Faults(err, 1)
	}
}

// WithKeyGeneratorGenerateKey returns the option that sets the function of
// GenerateKey.
func WithKeyGeneratorGenerateKey(fn func(context.Context, int) ([]byte, []byte, error)) KeyGeneratorStubOption {
	return func(s *KeyGeneratorStub) { s.OnGenerateKey.Func(fn) }
}

